const queryClient = new QueryClient();

function refreshWorkspace() {
  void queryClient.invalidateQueries({ queryKey: getGetLayoutQueryKey() });
  void queryClient.invalidateQueries({ queryKey: getGetDrcResultsQueryKey() });
  void queryClient.invalidateQueries({ queryKey: getGetConstraintGraphQueryKey() });
  void queryClient.invalidateQueries({ queryKey: getGetResultsQueryKey() });
  void queryClient.invalidateQueries({ queryKey: getGetGeometryDiffQueryKey() });
}

const emptySummary: LayoutSummary = {
  id: 'not-loaded',
  source: 'none',
  technology: 'not selected',
  design: 'No active layout',
  dieWidth: 0,
  dieHeight: 0,
  cells: 0,
  nets: 0,
  pins: 0,
  wires: 0,
  vias: 0,
  layers: 0,
  parsedAt: '',
  warnings: [],
};
const emptyLayout: Layout = { summary: emptySummary, objects: [] };
const emptyDrc: DrcResults = {
  status: 'NOT RUN',
  total: 0,
  affectedNets: 0,
  affectedCells: 0,
  ranAt: '',
  byType: {},
  byLayer: {},
  bySeverity: {},
  violations: [],
};
const emptyGraph: ConstraintGraph = {
  components: 0,
  clusters: 0,
  builtAt: '',
  nodes: [],
  edges: [],
};
const emptyDiff: GeometryDiff = { status: 'NOT MEASURED', counts: { added: 0, removed: 0, modified: 0, unchanged: 0 }, entries: [] };

const nav = [
  { href: '/', label: 'Workspace', icon: LayoutDashboard },
  { href: '/input', label: 'Input', icon: Upload },
  { href: '/viewer', label: 'Layout viewer', icon: ScanSearch },
  { href: '/drc', label: 'DRC results', icon: ShieldCheck },
  { href: '/graph', label: 'Constraint graph', icon: Network },
  { href: '/repair', label: 'Repair lab', icon: WandSparkles },
  { href: '/training', label: 'Training', icon: LineChart },
  { href: '/experiments', label: 'Experiments', icon: Beaker },
];

function useData() {
  const health = useHealthCheck();
  const techs = useListTechnologies();
  const layoutQuery = useGetLayout();
  const drcQuery = useGetDrcResults();
  const graphQuery = useGetConstraintGraph();
  const resultsQuery = useGetResults();
  const diffQuery = useGetGeometryDiff();
  const experimentsQuery = useListExperiments();
  const layout = layoutQuery.data ?? emptyLayout;
  const drc = drcQuery.data ?? emptyDrc;
  const graph = graphQuery.data ?? emptyGraph;
  const diff = diffQuery.data ?? emptyDiff;
  const technologies = techs.data ?? [];
  return { health, techs, layout, drc, graph, diff, results: resultsQuery.data, experiments: experimentsQuery.data ?? [], layoutQuery, drcQuery, graphQuery, diffQuery, resultsQuery, experimentsQuery, technologies };
}

