function PageHead({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mono mb-2 text-[10px] font-medium uppercase tracking-[.2em] text-primary">{eyebrow}</div><h1 className="text-2xl font-extrabold tracking-[-.035em] text-foreground md:text-[30px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-[12px] leading-5 text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function Panel({ title, meta, children, className = '' }: { title: string; meta?: string; children: ReactNode; className?: string }) {
  return <section className={`border border-card-border bg-card ${className}`}><div className="flex items-center justify-between border-b border-border px-4 py-3"><h2 className="text-[11px] font-extrabold uppercase tracking-[.12em]">{title}</h2>{meta && <span className="mono text-[9px] uppercase text-muted-foreground">{meta}</span>}</div>{children}</section>;
}
function Button({ children, onClick, kind = 'primary', disabled, testId }: { children: ReactNode; onClick?: () => void; kind?: 'primary' | 'quiet' | 'outline' | 'danger'; disabled?: boolean; testId: string }) {
  const style = kind === 'primary' ? 'bg-primary text-primary-foreground hover:brightness-110' : kind === 'danger' ? 'border border-destructive/40 bg-destructive/10 text-destructive hover:bg-destructive/15' : kind === 'outline' ? 'border border-border bg-card text-foreground hover:border-primary/50 hover:text-primary' : 'border border-transparent bg-muted text-muted-foreground hover:bg-secondary hover:text-foreground';
  return <button data-testid={testId} disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 px-3.5 py-2 text-[11px] font-bold transition-all disabled:cursor-not-allowed disabled:opacity-45 ${style}`}>{children}</button>;
}
function Stat({ label, value, sub, tone = 'default' }: { label: string; value: React.ReactNode; sub?: string; tone?: 'default' | 'good' | 'warn' | 'danger' }) {
  const color = tone === 'good' ? 'text-emerald-600' : tone === 'warn' ? 'text-amber-600' : tone === 'danger' ? 'text-destructive' : 'text-foreground';
  return <div className="border border-border bg-card px-4 py-4"><div className="mono text-[9px] uppercase tracking-[.13em] text-muted-foreground">{label}</div><div className={`mt-2 text-2xl font-extrabold tracking-[-.05em] ${color}`} data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</div>{sub && <div className="mono mt-1 text-[9px] text-muted-foreground">{sub}</div>}</div>;
}
function Skeleton({ rows = 3 }: { rows?: number }) { return <div className="space-y-3 p-4">{Array.from({ length: rows }, (_, i) => <div key={i} className="h-8 animate-pulse bg-muted" />)}</div>; }
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) { return <div className="flex min-h-[180px] flex-col items-center justify-center px-6 text-center"><div className="mb-3 grid h-10 w-10 place-items-center border border-dashed border-primary/40 text-primary"><Grid3X3 size={18} /></div><div className="text-sm font-bold">{title}</div><div className="mt-1 max-w-sm text-[11px] leading-5 text-muted-foreground">{detail}</div>{action && <div className="mt-4">{action}</div>}</div>; }
function ErrorNote({ onRetry }: { onRetry?: () => void }) { return <div className="flex items-center justify-between gap-3 border border-destructive/25 bg-destructive/5 px-4 py-3 text-[11px] text-destructive"><span className="flex items-center gap-2"><AlertTriangle size={14} /> Engine response unavailable; showing the last known instrument state.</span>{onRetry && <Button testId="button-retry" kind="danger" onClick={onRetry}><RefreshCw size={12} /> Retry</Button>}</div>; }

function Workspace() {
  const { layout, drc, graph, layoutQuery, drcQuery } = useData();
  const runDrc = useRunDrc();
  const [notice, setNotice] = useState('');
  const healthText = drc.status === 'complete' ? 'within bounds' : drc.status;
  return <div className="animate-rise">
    <PageHead eyebrow="Workspace / run 042" title="Physical design control room" description="Inspect geometry, evaluate rule dependencies, and validate bounded repair actions against the active benchmark." action={<div className="flex gap-2"><Link href="/input" data-testid="link-new-layout" className="inline-flex items-center gap-2 bg-primary px-3.5 py-2 text-[11px] font-bold text-primary-foreground hover:brightness-110"><Upload size={13} /> New layout</Link><Button testId="button-run-drc" onClick={() => { setNotice('DRC run queued against active layout.'); runDrc.mutate(undefined, { onSuccess: refreshWorkspace }); }} disabled={runDrc.isPending}><Play size={12} /> {runDrc.isPending ? 'Running…' : 'Run DRC'}</Button></div>} />
    {(layoutQuery.isError || drcQuery.isError) && <div className="mb-5"><ErrorNote onRetry={() => { layoutQuery.refetch(); drcQuery.refetch(); }} /></div>}
    {notice && <div className="mb-5 border border-primary/25 bg-primary/5 px-4 py-3 text-[11px] text-primary" data-testid="status-run-drc">{notice}</div>}
     <div className="grid grid-cols-2 gap-3 md:grid-cols-4 lg:grid-cols-6 animate-rise-2"><Stat label="Cells" value={layout.summary.cells} sub="placed instances" /><Stat label="Nets" value={layout.summary.nets} sub="routed connectivity" /><Stat label="Die area" value={`${(layout.summary.dieWidth * layout.summary.dieHeight / 1000000).toFixed(2)} mm²`} sub={`${layout.summary.dieWidth} × ${layout.summary.dieHeight} µm`} /><Stat label="Violations" value={drc.total} sub={`${drc.affectedNets} nets affected`} tone={drc.status === 'NOT RUN' ? 'default' : drc.total ? 'danger' : 'good'} /><Stat label="Layers" value={layout.summary.layers} sub={`${layout.summary.vias} vias`} /><Stat label="Engine" value={healthText} sub="latest DRC pass" tone={drc.status === 'NOT RUN' ? 'default' : 'good'} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]">
      <Panel title="Layout telemetry" meta="live geometry snapshot"><div className="instrument-grid relative min-h-[290px] overflow-hidden bg-[#eef3f4] p-5 dark:bg-[#152025]"><div className="absolute left-[10%] top-[17%] h-[66%] w-[76%] border border-primary/35"><div className="absolute inset-3 border border-primary/15" /></div><svg viewBox="0 0 800 300" className="relative z-10 h-[290px] w-full"><path d="M80 236 H200 L300 170 H460 L540 92 H730" fill="none" stroke="#0d8490" strokeWidth="3" opacity=".72" /><path d="M130 70 H270 L350 130 H590 L700 214" fill="none" stroke="#d18b27" strokeWidth="2" opacity=".8" /><path d="M145 260 V118 H385 V50 H660" fill="none" stroke="#5b7a91" strokeWidth="1.5" opacity=".65" /><g fill="#f7faf9" stroke="#0d8490" strokeWidth="2">{[[80,226],[200,226],[300,160],[460,160],[540,82],[730,82],[130,60],[270,60],[350,120],[590,120],[700,204],[145,250],[145,118],[385,118],[385,50],[660,50]].map(([x,y], i) => <circle key={i} cx={x} cy={y} r="5" />)}</g><rect x="295" y="148" width="90" height="30" fill="#0d8490" fillOpacity=".11" stroke="#0d8490" strokeDasharray="3 3" /><rect x="518" y="69" width="86" height="30" fill="#d95f45" fillOpacity=".17" stroke="#d95f45" strokeWidth="2" /></svg><div className="absolute bottom-4 left-5 flex gap-4 mono text-[9px] text-muted-foreground"><span><i className="mr-1 inline-block h-2 w-2 bg-primary" /> signal</span><span><i className="mr-1 inline-block h-2 w-2 bg-accent" /> clock</span><span><i className="mr-1 inline-block h-2 w-2 bg-destructive" /> violation</span></div></div></Panel>
       <Panel title="Run status" meta="pipeline"><div className="space-y-0 px-4 py-2">{[['01', 'Layout parsed', layout.objects.length ? 'complete' : 'not loaded'], ['02', 'Rule engine', drc.status], ['03', 'Constraint graph', graph.nodes.length ? 'ready' : 'not built'], ['04', 'Repair agent', 'not initialized']].map(([n, label, state], i) => <div key={n} className="flex items-center gap-3 border-b border-border py-3 last:border-0"><span className="mono text-[10px] text-muted-foreground">{n}</span><span className={`grid h-6 w-6 place-items-center ${state === 'complete' || state === 'ready' ? 'bg-emerald-500/10 text-emerald-600' : state === 'not loaded' || state === 'not built' || state === 'not initialized' ? 'bg-muted text-muted-foreground' : 'bg-amber-500/10 text-amber-600'}`}>{state === 'complete' || state === 'ready' ? <Check size={13} /> : <Activity size={13} />}</span><div className="flex-1 text-[11px] font-bold">{label}</div><span className="mono text-[9px] uppercase text-muted-foreground">{state}</span></div>)}</div><div className="border-t border-border bg-muted/35 px-4 py-4"><div className="mono text-[9px] uppercase text-muted-foreground">Current repair state</div><div className="mt-2 flex items-end justify-between"><div><div className="text-lg font-extrabold">Not initialized</div><div className="mono text-[10px] text-muted-foreground">No actions committed</div></div><Link href="/repair" data-testid="link-open-repair" className="text-primary hover:text-foreground"><ArrowRight size={18} /></Link></div></div></Panel>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-3">
      <Panel title="Violation mix" meta={`${drc.total} total`}><div className="space-y-4 px-4 py-5">{Object.entries(drc.byType).map(([key, value]) => <div key={key}><div className="mb-1.5 flex justify-between text-[10px]"><span className="font-semibold">{key}</span><span className="mono text-muted-foreground">{value}</span></div><div className="h-1.5 bg-muted"><div className="h-full bg-primary" style={{ width: `${Math.max(8, (value / Math.max(drc.total, 1)) * 100)}%` }} /></div></div>)}</div></Panel>
      <Panel title="Quick actions"><div className="grid gap-px bg-border">{[['/viewer', ScanSearch, 'Inspect layout', 'Layer-aware geometry view'], ['/graph', Network, 'Build graph', 'Map constraints and dependencies'], ['/training', LineChart, 'Train agent', 'Bounded DQN simulation']].map(([href, Icon, label, detail]) => <Link href={href as string} key={label as string} data-testid={`link-quick-${label}`} className="flex items-center gap-3 bg-card px-4 py-3.5 hover:bg-muted"><span className="grid h-8 w-8 place-items-center bg-primary/10 text-primary"><Icon size={15} /></span><span className="flex-1"><span className="block text-[11px] font-bold">{label as string}</span><span className="block text-[10px] text-muted-foreground">{detail as string}</span></span><ChevronRight size={14} className="text-muted-foreground" /></Link>)}</div></Panel>
      <Panel title="Benchmark profile"><div className="px-4 py-5"><div className="mono text-[10px] text-primary">TECHNOLOGY PROFILE</div><div className="mt-2 text-lg font-extrabold">{layout.summary.technology.toUpperCase()}</div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">Deterministic synthetic benchmark with {layout.summary.layers} routing layers and technology-aware spacing rules.</p><div className="signal-rule mt-5" /><div className="mt-3 flex justify-between mono text-[9px] text-muted-foreground"><span>SOURCE</span><span>{layout.summary.source}</span></div></div></Panel>
    </div>
  </div>;
}

function InputPage() {
  const { technologies } = useData();
  const [tech, setTech] = useState('sky130'); const [seed, setSeed] = useState('42'); const [defText, setDefText] = useState(''); const [lefText, setLefText] = useState(''); const [mode, setMode] = useState<'demo' | 'parse'>('demo'); const [message, setMessage] = useState('');
  const demo = useGenerateDemoLayout(); const parse = useParseLayout();
  const profiles = technologies;
  const submit = () => { setMessage(''); if (mode === 'demo') demo.mutate({ data: { technology: tech, seed: Number(seed) } }, { onSuccess: () => { refreshWorkspace(); setMessage('Synthetic benchmark generated. Workspace is ready.'); }, onError: () => setMessage('Generation failed. Check the engine connection and retry.') }); else parse.mutate({ data: { technology: tech, defText, lefText } }, { onSuccess: () => { refreshWorkspace(); setMessage('DEF/LEF parsed into the active workspace.'); }, onError: () => setMessage('Parser rejected the source text. Confirm both inputs are non-empty.') }); };
  return <div className="animate-rise"><PageHead eyebrow="Input / source control" title="Stage a layout benchmark" description="Select a technology-aware ruleset, then generate a deterministic fixture or parse a DEF/LEF pair into the active workspace." /><div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><Panel title="Technology profile" meta="required"><div className="space-y-2 p-4">{profiles.length ? profiles.map((item) => <button key={item.id} data-testid={`button-technology-${item.id}`} onClick={() => setTech(item.id)} className={`w-full border px-4 py-3 text-left transition-colors ${tech === item.id ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'}`}><div className="flex items-center justify-between"><span className="text-[12px] font-bold">{item.name}</span><span className="mono text-[9px] uppercase text-muted-foreground">{item.status}</span></div><div className="mt-1 text-[10px] text-muted-foreground">{item.description}</div><div className="mt-2 flex flex-wrap gap-1">{item.availableRules.map((rule) => <span key={rule} className="bg-muted px-1.5 py-0.5 mono text-[8px] text-muted-foreground">{rule}</span>)}</div></button>) : <EmptyState title="Engine profiles unavailable" detail="Start the API engine to load technology profiles." />}</div></Panel><Panel title="Layout source" meta={mode === 'demo' ? 'synthetic' : 'parser'}><div className="flex border-b border-border px-4 pt-3"><button data-testid="button-mode-demo" onClick={() => setMode('demo')} className={`border-b-2 px-3 pb-3 text-[11px] font-bold ${mode === 'demo' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`}>Generate benchmark</button><button data-testid="button-mode-parse" onClick={() => setMode('parse')} className={`border-b-2 px-3 pb-3 text-[11px] font-bold ${mode === 'parse' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`}>Parse DEF / LEF</button></div>{mode === 'demo' ? <div className="p-5"><div className="flex items-start gap-4 border border-primary/20 bg-primary/5 p-4"><Sparkles size={18} className="mt-0.5 text-primary" /><div><div className="text-sm font-bold">Deterministic synthetic benchmark</div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">Creates a reproducible routed design with clustered violations, useful for comparing repair policies across runs.</p></div></div><label className="mt-5 block text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Seed<input data-testid="input-seed" value={seed} onChange={(e) => setSeed(e.target.value)} type="number" className="mt-2 block w-full border border-input bg-background px-3 py-2.5 mono text-[12px] outline-none focus:border-primary" /></label></div> : <div className="grid gap-4 p-5 md:grid-cols-2"><label className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">DEF text<textarea data-testid="input-def-text" value={defText} onChange={(e) => setDefText(e.target.value)} placeholder="VERSION 5.8 ;&#10;DESIGN orion_ctrl ;" className="mt-2 h-44 w-full resize-none border border-input bg-background p-3 mono text-[10px] outline-none focus:border-primary" /></label><label className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">LEF text<textarea data-testid="input-lef-text" value={lefText} onChange={(e) => setLefText(e.target.value)} placeholder="VERSION 5.8 ;&#10;LAYER metal1 ..." className="mt-2 h-44 w-full resize-none border border-input bg-background p-3 mono text-[10px] outline-none focus:border-primary" /></label></div>}<div className="flex items-center justify-between border-t border-border bg-muted/30 px-5 py-4">{message && <span className="text-[11px] text-primary" data-testid="status-input">{message}</span>}<span className="ml-auto"><Button testId="button-submit-layout" onClick={submit} disabled={demo.isPending || parse.isPending || !profiles.length}>{demo.isPending || parse.isPending ? <Activity size={13} /> : <ArrowRight size={13} />}{demo.isPending || parse.isPending ? 'Processing…' : mode === 'demo' ? 'Generate layout' : 'Parse source'}</Button></span></div></Panel></div></div>;
}

function Viewer() {
  const { layout, drc } = useData();
  const [layers, setLayers] = useState<Record<string, boolean>>({});
  const [selected, setSelected] = useState<string | null>(null);
  const [showViolations, setShowViolations] = useState(true);
  const [zoom, setZoom] = useState(1);
  const colors: Record<string, string> = { M1: '#0d8490', M2: '#d18b27', M3: '#536f9b', VIA1: '#ae5d8f', VIA2: '#5d8d68', CELL: '#607b87', pin: '#8a5c9f' };
  const layerNames = Array.from(new Set(layout.objects.map((object) => object.layer)));
  const selectedObject = layout.objects.find((object) => object.id === selected);
  return <div className="animate-rise">
    <PageHead eyebrow="Viewer / geometry inspection" title="Layout viewer" description="Select objects to inspect connectivity and switch routing layers or violation overlays without losing the physical context." action={<div className="flex gap-2"><Button testId="button-fit-layout" kind="outline" onClick={() => setZoom(1)}><Target size={13} /> Fit layout</Button><Button testId="button-zoom-in" kind="quiet" onClick={() => setZoom((value) => Math.min(2.5, value + .15))}>+</Button><Button testId="button-zoom-out" kind="quiet" onClick={() => setZoom((value) => Math.max(.65, value - .15))}>−</Button></div>} />
    <div className="grid gap-5 xl:grid-cols-[1fr_285px]">
      <Panel title="SVG inspection canvas" meta={`${layout.objects.length} objects · ${layout.summary.dieWidth} × ${layout.summary.dieHeight}`}>
        <div className="instrument-grid min-h-[590px] overflow-hidden bg-[#edf3f3] p-5 dark:bg-[#142024]">
          {layout.objects.length ? <svg viewBox="0 0 1000 650" className="h-[590px] w-full" onWheel={(event) => { event.preventDefault(); setZoom((value) => Math.max(.65, Math.min(2.5, value + (event.deltaY < 0 ? .08 : -.08)))); }}>
            <g transform={`translate(${500 - 500 * zoom} ${325 - 325 * zoom}) scale(${zoom})`}>
              <rect x="60" y="40" width="880" height="570" fill="rgba(255,255,255,.4)" stroke="#7797a2" strokeDasharray="6 5" />
              <g opacity=".4" stroke="#8aa4ad" strokeWidth="1">{Array.from({ length: 14 }, (_, i) => <line key={`h${i}`} x1="60" y1={70 + i * 40} x2="940" y2={70 + i * 40} />)}{Array.from({ length: 22 }, (_, i) => <line key={`v${i}`} x1={80 + i * 40} y1="40" x2={80 + i * 40} y2="610" />)}</g>
              {layout.objects.filter((object) => layers[object.layer] !== false).map((object) => <g key={object.id} onClick={() => setSelected(object.id)} className="cursor-pointer">
                <rect x={object.x * .8 + 70} y={object.y * .85 + 55} width={Math.max(6, object.width * .5)} height={Math.max(5, object.height * .7)} fill={colors[object.layer] ?? '#0d8490'} fillOpacity={selected === object.id ? '.3' : object.kind === 'cell' ? '.08' : '.14'} stroke={selected === object.id ? '#d95f45' : colors[object.layer] ?? '#0d8490'} strokeWidth={selected === object.id ? 3 : 1.5} />
                <text x={object.x * .8 + 76} y={object.y * .85 + 70} fontSize={object.kind === 'cell' ? 8 : 9} fill="#263d48">{object.label}</text>
              </g>)}
              {showViolations && drc.violations.map((violation) => <g key={violation.id} onClick={() => setSelected(violation.objectId)} className="cursor-pointer">
                <rect x={violation.x * .8 + 70} y={violation.y * .85 + 55} width={Math.max(12, violation.width * .5)} height={Math.max(10, violation.height * .7)} fill={violation.severity === 'error' ? '#d95f45' : '#d18b27'} fillOpacity=".2" stroke={violation.severity === 'error' ? '#d95f45' : '#d18b27'} strokeWidth="2" />
                <circle cx={violation.x * .8 + 76} cy={violation.y * .85 + 61} r="4" fill={violation.severity === 'error' ? '#d95f45' : '#d18b27'} />
              </g>)}
            </g>
          </svg> : <EmptyState title="No layout loaded" detail="Generate a synthetic benchmark or parse DEF/LEF from the Input page." />}
        </div>
      </Panel>
      <Panel title="Visibility & selection" meta="controls">
        <div className="border-b border-border p-4">
          <div className="mono mb-3 text-[9px] uppercase text-muted-foreground">Layers</div>
          {layerNames.map((layer) => <label key={layer} className="flex cursor-pointer items-center justify-between py-2"><span className="flex items-center gap-2 text-[11px] font-semibold"><span className="h-2 w-2" style={{ backgroundColor: colors[layer] ?? '#0d8490' }} />{layer}</span><input data-testid={`input-toggle-${layer}`} type="checkbox" checked={layers[layer] !== false} onChange={() => setLayers((old) => ({ ...old, [layer]: old[layer] === false }))} className="accent-primary" /></label>)}
          <label className="mt-2 flex cursor-pointer items-center justify-between border-t border-border pt-3 text-[11px] font-semibold"><span className="flex items-center gap-2"><AlertTriangle size={13} className="text-destructive" /> violations</span><input data-testid="input-toggle-violations" type="checkbox" checked={showViolations} onChange={() => setShowViolations(!showViolations)} className="accent-primary" /></label>
        </div>
        <div className="bg-muted/30 p-4">{selectedObject ? <><div className="mono text-[9px] uppercase text-primary">Selected object</div><div className="mt-2 flex items-center justify-between"><span className="text-sm font-extrabold">{selectedObject.id}</span><span className="mono text-[9px] text-muted-foreground">{selectedObject.kind}</span></div><div className="mt-4 space-y-2 text-[10px]">{[['layer', selectedObject.layer], ['net', selectedObject.net || '—'], ['geometry', `${selectedObject.width} × ${selectedObject.height}`]].map(([key, value]) => <div className="flex justify-between border-b border-border pb-2" key={key}><span className="text-muted-foreground">{key}</span><span className="mono">{value}</span></div>)}</div></> : <div className="text-[11px] text-muted-foreground">Select an object or violation on the canvas.</div>}</div>
      </Panel>
    </div>
  </div>;
}

function DrcPage() {
  const { drc, drcQuery } = useData(); const [filter, setFilter] = useState('all'); const [selected, setSelected] = useState(drc.violations[0]?.id ?? ''); const runDrc = useRunDrc();
  const rows = drc.violations.filter((v) => filter === 'all' || v.severity === filter || v.type === filter); const violation = drc.violations.find((v) => v.id === selected) ?? rows[0];
  return <div className="animate-rise"><PageHead eyebrow="DRC / rule engine" title="Design-rule results" description="Review measurable spacing, width, enclosure, and connectivity findings from the latest technology-aware pass." action={<Button testId="button-rerun-drc" onClick={() => runDrc.mutate(undefined, { onSuccess: refreshWorkspace })} disabled={runDrc.isPending}><RefreshCw size={13} className={runDrc.isPending ? 'animate-spin' : ''} /> {runDrc.isPending ? 'Running…' : 'Re-run checks'}</Button>} />{drcQuery.isError && <div className="mb-5"><ErrorNote onRetry={() => drcQuery.refetch()} /></div>}<div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Stat label="Total findings" value={drc.total} tone="danger" /><Stat label="Errors" value={drc.bySeverity.error ?? 0} tone="danger" /><Stat label="Warnings" value={drc.bySeverity.warning ?? 0} tone="warn" /><Stat label="Affected nets" value={drc.affectedNets} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_330px]"><Panel title="Violation queue" meta={`${rows.length} shown`}><div className="flex flex-wrap gap-2 border-b border-border bg-muted/25 p-3"><select data-testid="select-drc-filter" value={filter} onChange={(e) => setFilter(e.target.value)} className="border border-input bg-background px-3 py-2 text-[10px] outline-none"><option value="all">All findings</option><option value="error">Errors</option><option value="warning">Warnings</option>{Object.keys(drc.byType).map((type) => <option value={type} key={type}>{type}</option>)}</select><span className="ml-auto mono self-center text-[9px] text-muted-foreground">SORT: SEVERITY</span></div>{drcQuery.isLoading ? <Skeleton /> : rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="bg-muted/40 mono text-[9px] uppercase text-muted-foreground"><tr><th className="px-4 py-3">ID</th><th>Rule</th><th>Type</th><th>Layer</th><th>Measured</th><th>Status</th></tr></thead><tbody className="divide-y divide-border">{rows.map((v) => <tr key={v.id} data-testid={`row-violation-${v.id}`} onClick={() => setSelected(v.id)} className={`cursor-pointer text-[11px] hover:bg-primary/5 ${v.id === selected ? 'bg-primary/5' : ''}`}><td className="px-4 py-3 mono font-medium text-primary">{v.id}</td><td className="mono">{v.rule}</td><td>{v.type}</td><td className="mono">{v.layer}</td><td className="mono">{v.measured.toFixed(2)} / {v.required.toFixed(2)}</td><td><span className={`inline-flex items-center gap-1 text-[10px] font-bold uppercase ${v.severity === 'error' ? 'text-destructive' : 'text-amber-600'}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{v.severity}</span></td></tr>)}</tbody></table></div> : <EmptyState title="No findings in this filter" detail="Change the severity or rule filter to restore the result queue." />}</Panel><Panel title="Selected finding" meta={violation?.id ?? 'none'}>{violation ? <div className="p-4"><div className="flex items-start justify-between"><div><div className="mono text-[10px] text-primary">{violation.rule}</div><div className="mt-1 text-lg font-extrabold">{violation.type}</div></div><span className="border border-destructive/30 bg-destructive/5 px-2 py-1 mono text-[9px] uppercase text-destructive">{violation.severity}</span></div><div className="mt-5 space-y-3 text-[11px]">{[['Layer', violation.layer], ['Object', violation.objectId], ['Net', violation.net], ['Measured', `${violation.measured.toFixed(2)} µm`], ['Required', `${violation.required.toFixed(2)} µm`], ['Delta', `${violation.amount.toFixed(2)} µm`]].map(([key, value]) => <div className="flex justify-between border-b border-border pb-2" key={key}><span className="text-muted-foreground">{key}</span><span className="mono">{value}</span></div>)}</div><div className="mt-5 mono text-[9px] uppercase text-muted-foreground">Suggested actions</div><div className="mt-2 space-y-2">{violation.suggestedActions.map((action) => <div key={action} className="flex items-center gap-2 bg-muted px-3 py-2 text-[10px]"><ArrowRight size={11} className="text-primary" />{action}</div>)}</div><Link href="/repair" data-testid="link-repair-selected" className="mt-5 flex items-center justify-center gap-2 bg-primary px-3 py-2.5 text-[11px] font-bold text-primary-foreground"><WandSparkles size={13} /> Open in repair lab</Link></div> : <EmptyState title="Nothing selected" detail="Select a violation from the queue." />}</Panel></div></div>;
}

function GraphPage() {
  const { graph, graphQuery } = useData(); const build = useBuildConstraintGraph(); const [relation, setRelation] = useState('all'); const edges = graph.edges.filter((e) => relation === 'all' || e.relation === relation);
  return <div className="animate-rise"><PageHead eyebrow="Graph / dependency model" title="Constraint graph" description="Relationships turn isolated rule findings into a repair order. Inspect components, clusters, and edge semantics before committing an action." action={<Button testId="button-build-graph" onClick={() => build.mutate(undefined, { onSuccess: refreshWorkspace })} disabled={build.isPending}><GitBranch size={13} /> {build.isPending ? 'Building…' : 'Rebuild graph'}</Button>} /><div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Stat label="Nodes" value={graph.nodes.length} sub="layout objects" /><Stat label="Edges" value={graph.edges.length} sub="constraint relations" /><Stat label="Components" value={graph.components} /><Stat label="Clusters" value={graph.clusters} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_300px]"><Panel title="Topology" meta="force layout · normalized"><div className="instrument-grid min-h-[510px] bg-[#edf3f3] p-5 dark:bg-[#142024]"><svg viewBox="0 0 900 520" className="h-[500px] w-full"><g stroke="#9bb1b6" strokeWidth="1.5">{edges.map((e) => { const s = graph.nodes.find((n) => n.id === e.source); const t = graph.nodes.find((n) => n.id === e.target); if (!s || !t) return null; return <line key={e.id} x1={s.x * .52 + 110} y1={s.y * .37 + 70} x2={t.x * .52 + 110} y2={t.y * .37 + 70} stroke={e.relation === 'same-net' ? '#0d8490' : e.relation === 'timing' ? '#d18b27' : '#9bb1b6'} />; })}</g>{graph.nodes.map((n, i) => <g key={n.id}><circle cx={n.x * .52 + 110} cy={n.y * .37 + 70} r={10 + n.degree} fill={i % 3 === 0 ? '#0d8490' : '#dbe9e9'} stroke="#0d8490" strokeWidth="2" /><text x={n.x * .52 + 110} y={n.y * .37 + 74} textAnchor="middle" fontSize="8" fill={i % 3 === 0 ? 'white' : '#26434a'}>{n.label.slice(-4)}</text></g>)}</svg></div></Panel><Panel title="Relationship statistics" meta="edge index"><div className="border-b border-border p-4"><select data-testid="select-graph-relation" value={relation} onChange={(e) => setRelation(e.target.value)} className="w-full border border-input bg-background px-3 py-2 text-[10px] outline-none"><option value="all">All relations</option>{Array.from(new Set(graph.edges.map((e) => e.relation))).map((item) => <option key={item} value={item}>{item}</option>)}</select></div><div className="space-y-1 p-3">{edges.map((e) => <div key={e.id} className="flex items-center gap-2 border border-border px-3 py-2.5"><span className="h-2 w-2 rounded-full bg-primary" /><span className="flex-1 text-[10px] font-semibold">{e.source} → {e.target}</span><span className="mono text-[8px] text-muted-foreground">{e.relation}</span></div>)}</div>{graphQuery.isError && <div className="p-3"><ErrorNote onRetry={() => graphQuery.refetch()} /></div>}</Panel></div></div>;
}

function RepairPage() {
  const { drc } = useData();
  const [session, setSession] = useState<RepairSession | null>(null);
  const [preview, setPreview] = useState<RepairPreview | null>(null);
  const [action, setAction] = useState('ADJUST_GEOMETRY');
  const [maxSteps, setMaxSteps] = useState('25');
  const [seed, setSeed] = useState('42');
  const start = useStartRepair();
  const previewMutation = usePreviewRepairAction();
  const step = usePerformRepairStep();
  const undo = useUndoRepairAction();
  const reset = useResetRepairLayout();
  const run = useRunAutonomousRepair();
  const verify = useVerifyLayout({ mutation: { onSuccess: refreshWorkspace } });
  const current = session ?? { status: 'idle', episode: 0, step: 0, maxSteps: Number(maxSteps), initialViolations: drc.total, currentViolations: drc.total, currentReward: 0, actions: 0, history: [], epsilon: 1, connectivity: 'NOT INITIALIZED', currentViolation: drc.violations[0] ?? null } as RepairSession;
  const actionOptions = current.currentViolation?.suggestedActions ?? drc.violations[0]?.suggestedActions ?? [];
  const violationId = current.currentViolation?.id ?? drc.violations[0]?.id;
  const latestReward = current.history.at(-1)?.reward;
  const startSession = () => start.mutate(undefined, { onSuccess: (data) => { setSession(data); setPreview(null); } });
  const previewCandidate = () => { if (!violationId) return; previewMutation.mutate({ data: { action, violationId } }, { onSuccess: setPreview }); };
  const acceptCandidate = () => { if (!preview?.accepted) return; step.mutate({ data: { action: preview.action, violationId: preview.violationId } }, { onSuccess: (data) => { setSession(data); setPreview(null); refreshWorkspace(); } }); };
  const auto = () => run.mutate({ data: { maxSteps: Number(maxSteps), seed: Number(seed) } }, { onSuccess: (data) => { setSession(data); setPreview(null); refreshWorkspace(); } });
  const undoLast = () => undo.mutate(undefined, { onSuccess: (data) => { setSession(data); setPreview(null); refreshWorkspace(); } });
  const restoreInitial = () => reset.mutate(undefined, { onSuccess: () => { setSession(null); setPreview(null); refreshWorkspace(); } });
  return <div className="animate-rise"><PageHead eyebrow="Repair / bounded agent" title="Repair lab" description="Preview every candidate before committing it. Accepted actions must reduce total violations without introducing a new violation." action={<div className="flex flex-wrap gap-2"><Button testId="button-start-repair" kind="outline" onClick={startSession} disabled={start.isPending}><Radio size={13} /> Initialize</Button><Button testId="button-autonomous-repair" onClick={auto} disabled={run.isPending}>{run.isPending ? 'Running…' : <><WandSparkles size={13} /> Run bounded repair</>}</Button><Button testId="button-undo-repair" kind="quiet" onClick={undoLast} disabled={undo.isPending || !current.actions}><ArrowRight size={13} className="rotate-180" /> Undo</Button><Button testId="button-reset-repair" kind="danger" onClick={restoreInitial} disabled={reset.isPending}>Restore initial</Button></div>} /><div className="grid grid-cols-2 gap-3 md:grid-cols-5"><Stat label="Current violations" value={current.currentViolations} tone={current.currentViolations ? 'danger' : 'good'} /><Stat label="Actions" value={current.actions} /><Stat label="Reward" value={current.currentReward.toFixed(2)} tone={current.currentReward > 0 ? 'good' : 'default'} /><Stat label="Epsilon" value={current.epsilon.toFixed(2)} /><Stat label="Connectivity" value={current.connectivity} tone="good" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><Panel title="Control envelope" meta="candidate gate"><div className="space-y-5 p-5"><label className="block text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Maximum steps <input data-testid="input-max-steps" type="number" min="1" max="100" value={maxSteps} onChange={(e) => setMaxSteps(e.target.value)} className="mt-2 block w-full border border-input bg-background px-3 py-2.5 mono text-[12px] outline-none focus:border-primary" /></label><label className="block text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Episode seed <input data-testid="input-repair-seed" type="number" value={seed} onChange={(e) => setSeed(e.target.value)} className="mt-2 block w-full border border-input bg-background px-3 py-2.5 mono text-[12px] outline-none focus:border-primary" /></label><label className="block text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Action<select data-testid="select-repair-action" value={actionOptions.includes(action) ? action : actionOptions[0] ?? action} onChange={(e) => { setAction(e.target.value); setPreview(null); }} className="mt-2 block w-full border border-input bg-background px-3 py-2.5 mono text-[11px] outline-none focus:border-primary">{actionOptions.length ? actionOptions.map((item) => <option key={item}>{item}</option>) : <option>ADJUST_GEOMETRY</option>}</select></label><div className="border border-amber-500/30 bg-amber-500/5 p-3 text-[10px] leading-5 text-amber-700">Connectivity is treated as a hard invariant. A candidate is only accepted when the full DRC count decreases and no new violation signature appears.</div><div className="flex flex-wrap gap-2"><Button testId="button-preview-repair" kind="outline" onClick={previewCandidate} disabled={previewMutation.isPending || !violationId}><ScanSearch size={13} /> {previewMutation.isPending ? 'Previewing…' : 'Preview candidate'}</Button><Button testId="button-accept-repair" onClick={acceptCandidate} disabled={!preview?.accepted || step.isPending}><Check size={13} /> {step.isPending ? 'Accepting…' : 'Accept candidate'}</Button></div></div></Panel><Panel title="Candidate preview" meta={preview ? preview.status : 'not staged'}>{preview ? <div className="space-y-4 p-4"><div className="flex items-center justify-between border-b border-border pb-3 text-[11px]"><span className="text-muted-foreground">{preview.action}</span><span className={preview.accepted ? 'font-bold text-emerald-600' : 'font-bold text-destructive'}>{preview.status}</span></div><div className="grid grid-cols-2 gap-2"><Stat label="Before" value={preview.before} /><Stat label="Candidate" value={preview.after} tone={preview.accepted ? 'good' : 'danger'} /></div><div className="space-y-2 text-[10px]"><div className="flex justify-between border-b border-border pb-2"><span className="text-muted-foreground">Candidate objects</span><span className="mono">{preview.candidateObjects.length}</span></div><div className="flex justify-between border-b border-border pb-2"><span className="text-muted-foreground">Candidate DRC</span><span className="mono">{preview.candidateDrc.status}</span></div></div><div className="text-[10px] leading-5 text-muted-foreground">Preview is isolated from the active layout until you explicitly accept it.</div></div> : <EmptyState title="No candidate staged" detail="Choose an action and preview it before making a geometry change." />}</Panel></div><div className="mt-5"><Panel title="Step history" meta={`${current.history.length} recorded`}><div className="overflow-x-auto">{current.history.length ? <table className="w-full min-w-[660px] text-left"><thead className="bg-muted/35 mono text-[9px] uppercase text-muted-foreground"><tr><th className="px-4 py-3">Step</th><th>Action</th><th>Target</th><th>Violations</th><th>Reward</th><th>Status</th></tr></thead><tbody className="divide-y divide-border">{current.history.map((item) => <tr key={`${item.step}-${item.violationId}`} className="text-[10px]"><td className="px-4 py-3 mono text-primary">{String(item.step).padStart(2, '0')}</td><td className="font-semibold">{item.action}</td><td className="mono">{item.violationId}</td><td className="mono">{item.before} → {item.after}</td><td className={item.reward.total > 0 ? 'mono text-emerald-600' : 'mono text-destructive'}>{item.reward.total.toFixed(2)}</td><td className="uppercase text-emerald-600">{item.status}</td></tr>)}</tbody></table> : <EmptyState title="No repair actions yet" detail="Initialize the environment, then preview and accept a candidate or run a bounded episode." />}</div></Panel></div><div className="mt-5"><Panel title="Reward components" meta={latestReward ? 'latest measured transition' : 'not measured'}><div className="grid grid-cols-2 gap-px bg-border md:grid-cols-6">{[['Violation reduction', latestReward ? latestReward.violationReduction.toFixed(2) : 'Not measured'], ['New violations', latestReward ? latestReward.newViolations.toFixed(2) : 'Not measured'], ['Wirelength cost', latestReward ? latestReward.wirelengthCost.toFixed(2) : 'Not measured'], ['Via cost', latestReward ? latestReward.viaCost.toFixed(2) : 'Not measured'], ['Connectivity', latestReward ? latestReward.connectivityPenalty.toFixed(2) : 'Not measured'], ['Total', latestReward ? latestReward.total.toFixed(2) : 'Not measured']].map(([label, value]) => <div key={label} className="bg-card p-4"><div className="text-[10px] text-muted-foreground">{label}</div><div className={`mono mt-2 text-sm font-bold ${label === 'Total' ? 'text-primary' : ''}`}>{value}</div></div>)}</div></Panel></div><div className="mt-5 flex justify-end"><Button testId="button-verify-repair" kind="outline" onClick={() => verify.mutate()} disabled={verify.isPending}><ShieldCheck size={13} /> {verify.isPending ? 'Verifying…' : 'Verify current layout'}</Button></div></div>;
}

function TrainingPage() {
  const [form, setForm] = useState({ episodes: '120', learningRate: '.0005', gamma: '.92', epsilonStart: '1', epsilonEnd: '.08', seed: '42' }); const [result, setResult] = useState<TrainingResult | null>(null); const training = useRunTraining();
  const points = result?.points ?? [];
  const run = () => training.mutate({ data: { episodes: Number(form.episodes), learningRate: Number(form.learningRate), gamma: Number(form.gamma), epsilonStart: Number(form.epsilonStart), epsilonEnd: Number(form.epsilonEnd), seed: Number(form.seed) } }, { onSuccess: setResult });
  return <div className="animate-rise"><PageHead eyebrow="Training / DQN policy" title="Train the repair agent" description="Configure a bounded simulation and track reward, loss, capture rate, and residual violations across episodes." action={<Button testId="button-run-training" onClick={run} disabled={training.isPending}><Play size={13} /> {training.isPending ? 'Training…' : 'Run training'}</Button>} /><div className="grid gap-5 xl:grid-cols-[285px_1fr]"><Panel title="Configuration" meta="DQN"><div className="space-y-4 p-4">{Object.entries(form).map(([key, value]) => <label key={key} className="block text-[9px] font-bold uppercase tracking-[.12em] text-muted-foreground">{key.replace(/([A-Z])/g, ' $1')}<input data-testid={`input-training-${key}`} value={value} onChange={(e) => setForm((old) => ({ ...old, [key]: e.target.value }))} type={key === 'episodes' || key === 'seed' ? 'number' : 'text'} className="mt-1.5 block w-full border border-input bg-background px-3 py-2 mono text-[11px] outline-none focus:border-primary" /></label>)}<div className="border-t border-border pt-4 mono text-[9px] text-muted-foreground">Agent: DQN<br />Replay memory and optimizer state are scoped to this bounded run.</div></div></Panel><div className="space-y-5"><Panel title="Reward trajectory" meta={result ? `${result.episodes} episodes` : 'not run'}><div className="p-4">{points.length ? <svg viewBox="0 0 900 220" className="h-[220px] w-full"><line x1="20" y1="190" x2="880" y2="190" stroke="#ccd8da" /><polyline fill="none" stroke="#0d8490" strokeWidth="3" points={points.map((p, i) => `${25 + i * (840 / Math.max(points.length - 1, 1))},${185 - Math.max(0, p.reward + 5) * 20}`).join(' ')} />{points.map((p, i) => <circle key={p.episode} cx={25 + i * (840 / Math.max(points.length - 1, 1))} cy={185 - Math.max(0, p.reward + 5) * 20} r="3.5" fill="#d18b27" />)}<text x="25" y="210" fontSize="9" fill="#71828a">episode 1</text><text x="825" y="210" fontSize="9" fill="#71828a">episode {points[points.length - 1]?.episode}</text></svg> : <EmptyState title="No training run yet" detail="Configure the bounded DQN simulation and run it to populate measured episode metrics." />}</div></Panel><Panel title="Metric series" meta="latest sample"><div className="overflow-x-auto">{points.length ? <table className="w-full min-w-[650px] text-left"><thead className="bg-muted/35 mono text-[9px] uppercase text-muted-foreground"><tr><th className="px-4 py-3">Episode</th><th>Reward</th><th>Loss</th><th>Epsilon</th><th>Capture rate</th><th>Violations</th></tr></thead><tbody className="divide-y divide-border">{points.slice(-6).map((p) => <tr key={p.episode} className="text-[10px]"><td className="px-4 py-3 mono text-primary">{p.episode}</td><td className="mono">{p.reward.toFixed(2)}</td><td className="mono">{p.loss.toFixed(3)}</td><td className="mono">{p.epsilon.toFixed(2)}</td><td className="mono text-emerald-600">{(p.captureRate * 100).toFixed(1)}%</td><td className="mono">{p.violations}</td></tr>)}</tbody></table> : <EmptyState title="No metric series yet" detail="Training metrics will appear here after the API returns a completed run." />}</div></Panel></div></div></div>;
}

function ExperimentsPage() {
  const { experiments } = useData(); const save = useSaveExperiment({ mutation: { onSuccess: () => { void queryClient.invalidateQueries({ queryKey: getListExperimentsQueryKey() }); } } }); const [saved, setSaved] = useState<Experiment | null>(null); const rows = saved ? [saved, ...experiments] : experiments;
  return <div className="animate-rise"><PageHead eyebrow="Experiments / archive" title="Saved experiment runs" description="Keep comparable repair runs together with their technology, seed, policy, and measured outcome." action={<Button testId="button-save-experiment" onClick={() => save.mutate({ data: { technology: 'sky130', design: 'orion_ctrl', seed: 42, method: 'bounded-dqn' } }, { onSuccess: setSaved })} disabled={save.isPending}><Save size={13} /> {save.isPending ? 'Saving…' : 'Save current run'}</Button>} /><Panel title="Run archive" meta={`${rows.length} runs`}><div className="overflow-x-auto">{rows.length ? <table className="w-full min-w-[850px] text-left"><thead className="bg-muted/35 mono text-[9px] uppercase text-muted-foreground"><tr><th className="px-4 py-3">Run</th><th>Date</th><th>Technology</th><th>Method</th><th>Initial</th><th>Final</th><th>Reward</th><th>Runtime</th><th>Status</th></tr></thead><tbody className="divide-y divide-border">{rows.map((e) => <tr key={e.id} data-testid={`row-experiment-${e.id}`} className="text-[10px] hover:bg-primary/5"><td className="px-4 py-3 mono text-primary">{e.id}</td><td className="mono">{new Date(e.date).toLocaleDateString()}</td><td className="font-semibold">{e.technology}</td><td>{e.method}</td><td className="mono">{e.initialViolations}</td><td className="mono text-emerald-600">{e.finalViolations}</td><td className="mono">{e.reward.toFixed(2)}</td><td className="mono">{typeof e.runtime === 'number' ? `${e.runtime.toFixed(1)}s` : e.runtime}</td><td><span className="text-emerald-600">{e.status}</span></td></tr>)}</tbody></table> : <EmptyState title="No archived runs" detail="Save the active run after a repair and verification pass." />}</div></Panel></div>;
}

function ReportsPage() {
  const { results, diff, diffQuery } = useData();
  const verify = useVerifyLayout({ mutation: { onSuccess: refreshWorkspace } });
  const def = useExportDef({ query: { enabled: false, queryKey: getExportDefQueryKey() } });
  const report = useExportReport({ query: { enabled: false, queryKey: getExportReportQueryKey() } });
  const verification: Verification | undefined = results?.verification;
  const download = (text: string | undefined, name: string) => { if (!text) return; const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url); };
  const finalTone = !verification ? 'default' : typeof verification.finalViolations === 'number' && verification.finalViolations > 0 ? 'warn' : 'good';
  const changedEntries = diff.entries.filter((entry) => entry.status !== 'UNCHANGED').slice(0, 10);
  return <div className="animate-rise"><PageHead eyebrow="Reports / verification" title="Verification & outputs" description="A final, auditable summary of baseline deltas, geometry changes, and exported-DEF revalidation. This is research output, not foundry signoff." action={<Button testId="button-final-verify" onClick={() => verify.mutate()} disabled={verify.isPending}><ShieldCheck size={13} /> {verify.isPending ? 'Verifying…' : 'Final verification'}</Button>} /><div className="border border-primary/25 bg-primary/5 p-4"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center bg-primary text-primary-foreground"><Check size={16} /></div><div><div className="text-[12px] font-extrabold">Verification gate is available</div><div className="text-[10px] text-muted-foreground">The gate captures the initial DRC once, compares the repaired layout against it, and reparses the exported DEF before reporting success.</div></div></div></div><div className="mt-5 grid grid-cols-2 gap-3 md:grid-cols-4"><Stat label="Initial violations" value={verification?.initialViolations ?? 'Not measured'} /><Stat label="Final violations" value={verification?.finalViolations ?? 'Not measured'} tone={finalTone} /><Stat label="Repaired" value={verification?.violationsRepaired ?? 'Not measured'} tone="good" /><Stat label="New violations" value={verification?.newViolations ?? 'Not measured'} tone="good" /></div><div className="mt-5 grid gap-5 md:grid-cols-2"><Panel title="Verification deltas" meta="baseline → current"><div className="space-y-3 p-4">{[['Wirelength geometry proxy', verification ? `${verification.wirelengthBefore} → ${verification.wirelengthAfter}` : 'Not measured'], ['Via count', verification ? `${verification.viaCountBefore} → ${verification.viaCountAfter}` : 'Not measured'], ['Congestion', verification ? `${verification.congestionBefore} → ${verification.congestionAfter}` : 'Not measured'], ['Connectivity', verification?.connectivity ?? 'Not measured']].map(([a, b]) => <div key={a} className="flex justify-between border-b border-border pb-3 text-[11px]"><span className="text-muted-foreground">{a}</span><span className="mono">{b}</span></div>)}</div></Panel><Panel title="Export revalidation" meta={verification?.exportParseStatus ?? 'not verified'}><div className="space-y-3 p-4 text-[11px]">{[['DEF parse', verification?.exportParseStatus ?? 'Not measured'], ['Export DRC', verification?.exportDrcStatus ?? 'Not measured'], ['Export violations', verification?.exportDrcViolations ?? 'Not measured']].map(([a, b]) => <div key={a} className="flex justify-between border-b border-border pb-3"><span className="text-muted-foreground">{a}</span><span className="mono">{b}</span></div>)}</div></Panel></div><div className="mt-5 grid gap-5 md:grid-cols-[.7fr_1.3fr]"><Panel title="Geometry diff" meta={diffQuery.isLoading ? 'loading' : diff.status}><div className="grid grid-cols-2 gap-px bg-border md:grid-cols-4">{[['Added', diff.counts.added], ['Removed', diff.counts.removed], ['Modified', diff.counts.modified], ['Unchanged', diff.counts.unchanged]].map(([label, value]) => <div key={label} className="bg-card p-4"><div className="text-[10px] text-muted-foreground">{label}</div><div className="mono mt-2 text-lg font-bold">{value}</div></div>)}</div>{changedEntries.length ? <div className="divide-y divide-border">{changedEntries.map((entry) => <div key={entry.id} className="flex items-center justify-between px-4 py-3 text-[10px]"><span className="mono text-primary">{entry.id}</span><span className="text-muted-foreground">{entry.kind}</span><span className={entry.status === 'REMOVED' ? 'text-destructive' : 'text-amber-600'}>{entry.status}</span></div>)}</div> : <EmptyState title="No geometry changes" detail="Run a repair or load a layout to populate the baseline diff." />}</Panel><Panel title="Downloadable outputs" meta="generated on demand"><div className="space-y-2 p-4"><Button testId="button-download-def" kind="outline" onClick={() => { def.refetch().then((r) => download(r.data, 'repaired_design.def')); }}><FileCode2 size={13} /> Download repaired DEF <Download size={12} className="ml-auto" /></Button><Button testId="button-download-report" kind="outline" onClick={() => { report.refetch().then((r) => download(r.data, 'drc_report.txt')); }}><FileText size={13} /> Download verification report <Download size={12} className="ml-auto" /></Button></div></Panel></div></div>;
}

function SettingsPage() {
  const { technologies } = useData(); return <div className="animate-rise"><PageHead eyebrow="Settings / environment" title="Technology & prototype limits" description="Review the profiles exposed by the rule engine and the boundaries of this research workstation." /><div className="grid gap-5 md:grid-cols-2"><Panel title="Technology profiles" meta={`${technologies.length} available`}><div className="divide-y divide-border">{technologies.length ? technologies.map((t) => <div key={t.id} className="p-4"><div className="flex justify-between"><span className="text-[12px] font-bold">{t.name}</span><span className="mono text-[9px] uppercase text-muted-foreground">{t.status}</span></div><p className="mt-1 text-[10px] text-muted-foreground">{t.description}</p><div className="mt-3 flex flex-wrap gap-1">{t.availableRules.map((r) => <span key={r} className="border border-border px-2 py-1 mono text-[9px]">{r}</span>)}</div></div>) : <EmptyState title="No profiles loaded" detail="Start the API engine to inspect technology rules." />}</div></Panel><Panel title="Prototype boundaries" meta="read-only"><div className="space-y-3 p-4">{['Supported rules are spacing, width, area, enclosure, and routing checks.', 'Repair actions are validated transforms, not arbitrary placement edits.', 'Training is a bounded simulation intended for policy comparison.', 'DEF export and professional text reporting are available after verification.'].map((text, i) => <div key={text} className="flex gap-3 border-b border-border pb-3 text-[11px] leading-5 last:border-0"><span className="mono text-primary">0{i + 1}</span><span>{text}</span></div>)}</div></Panel></div></div>;
}

function Router() {
  return <Shell><ErrorBoundary resetKey={location.pathname}><Switch><Route path="/" component={Workspace} /><Route path="/input" component={InputPage} /><Route path="/viewer" component={Viewer} /><Route path="/drc" component={DrcPage} /><Route path="/graph" component={GraphPage} /><Route path="/repair" component={RepairPage} /><Route path="/training" component={TrainingPage} /><Route path="/experiments" component={ExperimentsPage} /><Route path="/reports" component={ReportsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></ErrorBoundary></Shell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;